20	import * as zrUtil from 'zrender/src/core/util';
21	import ExtensionAPI from '../core/ExtensionAPI';
22	import GlobalModel from '../model/Global';
23	import Model from '../model/Model';
24	import SeriesModel from '../model/Series';
25	import {makeInner} from '../util/model';
26	import {Dictionary, DecalObject, InnerDecalObject, AriaOption} from '../util/types';
27	import {LocaleOption} from '../core/locale';
28	import { getDecalFromPalette } from '../model/mixin/palette';
29	import type {TitleOption} from '../component/title/install';
30	
31	const DEFAULT_OPTION: AriaOption = {
32	    label: {
33	        enabled: true
34	    },
35	    decal: {
36	        show: false
37	    }
38	};
39	
40	const inner = makeInner<{scope: object}, SeriesModel>();
41	
42	const decalPaletteScope: Dictionary<DecalObject> = {};
43	
44	type SeriesTypes = keyof LocaleOption['series']['typeNames'];
45	
46	export default function ariaVisual(ecModel: GlobalModel, api: ExtensionAPI) {
47	    const ariaModel: Model<AriaOption> = ecModel.getModel('aria');
48	
49	    // See "area enabled" detection code in `GlobalModel.ts`.
50	    if (!ariaModel.get('enabled')) {
51	        return;
52	    }
53	
54	    const defaultOption = zrUtil.clone(DEFAULT_OPTION);
55	    zrUtil.merge(defaultOption.label, ecModel.getLocaleModel().get('aria'), false);
56	    zrUtil.merge(ariaModel.option, defaultOption, false);
57	
58	    setDecal();
59	    setLabel();
60	
61	    function setDecal() {
62	        const decalModel = ariaModel.getModel('decal');
63	
64	        const useDecal = decalModel.get('show');
65	        if (useDecal) {
66	            // Each type of series use one scope.
67	            // Pie and funnel are using different scopes.
68	            const paletteScopeGroupByType = zrUtil.createHashMap<object>();
69	            ecModel.eachSeries((seriesModel: SeriesModel) => {
70	                if (seriesModel.isColorBySeries()) {
71	                    return;
72	                }
73	                let decalScope = paletteScopeGroupByType.get(seriesModel.type);
74	                if (!decalScope) {
75	                    decalScope = {};
76	                    paletteScopeGroupByType.set(seriesModel.type, decalScope);
77	                }
78	                inner(seriesModel).scope = decalScope;
79	            });
80	
81	            ecModel.eachRawSeries((seriesModel: SeriesModel) => {
82	                if (ecModel.isSeriesFiltered(seriesModel)) {
83	                    return;
84	                }
85	                if (zrUtil.isFunction(seriesModel.enableAriaDecal)) {
86	                    // Let series define how to use decal palette on data
87	                    seriesModel.enableAriaDecal();
88	                    return;
89	                }
90	
91	                const data = seriesModel.getData();
92	
93	                if (!seriesModel.isColorBySeries()) {
94	                    const dataAll = seriesModel.getRawData();
95	                    const idxMap: Dictionary<number> = {};
96	                    const decalScope = inner(seriesModel).scope;
97	
98	                    data.each(function (idx) {
99	                        const rawIdx = data.getRawIndex(idx);
100	                        idxMap[rawIdx] = idx;
101	                    });
102	
103	                    const dataCount = dataAll.count();
104	                    dataAll.each(rawIdx => {
105	                        const idx = idxMap[rawIdx];
106	                        const name = dataAll.getName(rawIdx) || (rawIdx + '');
107	                        const paletteDecal = getDecalFromPalette(
108	                            seriesModel.ecModel,
109	                            name,
110	                            decalScope,
111	                            dataCount
112	                        );
113	                        const specifiedDecal = data.getItemVisual(idx, 'decal');
114	                        data.setItemVisual(idx, 'decal', mergeDecal(specifiedDecal, paletteDecal));
115	                    });
116	                }
117	                else {
118	                    const paletteDecal = getDecalFromPalette(
119	                        seriesModel.ecModel,
120	                        seriesModel.name,
121	                        decalPaletteScope,
122	                        ecModel.getSeriesCount()
123	                    );
124	                    const specifiedDecal = data.getVisual('decal');
125	                    data.setVisual('decal', mergeDecal(specifiedDecal, paletteDecal));
126	                }
127	
128	                function mergeDecal(specifiedDecal: DecalObject, paletteDecal: DecalObject): DecalObject {
129	                    // Merge decal from palette to decal from itemStyle.
130	                    // User do not need to specify all of the decal props.
131	                    const resultDecal = specifiedDecal
132	                        ? zrUtil.extend(zrUtil.extend({}, paletteDecal), specifiedDecal)
133	                        : paletteDecal;
134	                    (resultDecal as InnerDecalObject).dirty = true;
135	                    return resultDecal;
136	                }
137	            });
138	        }
139	    }
140	
141	    function setLabel() {
142	        const labelLocale = ecModel.getLocaleModel().get('aria');
143	        const labelModel = ariaModel.getModel('label');
144	        labelModel.option = zrUtil.defaults(labelModel.option, labelLocale);
145	
146	        if (!labelModel.get('enabled')) {
147	            return;
148	        }
149	
150	        const dom = api.getZr().dom;
151	        if (labelModel.get('description')) {
152	            dom.setAttribute('aria-label', labelModel.get('description'));
153	            return;
154	        }
155	
156	        const seriesCnt = ecModel.getSeriesCount();
157	        const maxDataCnt = labelModel.get(['data', 'maxCount']) || 10;
158	        const maxSeriesCnt = labelModel.get(['series', 'maxCount']) || 10;
159	        const displaySeriesCnt = Math.min(seriesCnt, maxSeriesCnt);
160	
161	        let ariaLabel;
162	        if (seriesCnt < 1) {
163	            // No series, no aria label
164	            return;
165	        }
166	        else {
167	            const title = getTitle();
168	            if (title) {
169	                const withTitle = labelModel.get(['general', 'withTitle']);
170	                ariaLabel = replace(withTitle, {
171	                    title: title
172	                });
173	            }
174	            else {
175	                ariaLabel = labelModel.get(['general', 'withoutTitle']);
176	            }
177	
178	            const seriesLabels: string[] = [];
179	            const prefix = seriesCnt > 1
180	                ? labelModel.get(['series', 'multiple', 'prefix'])
181	                : labelModel.get(['series', 'single', 'prefix']);
182	            ariaLabel += replace(prefix, { seriesCount: seriesCnt });
183	
184	            ecModel.eachSeries(function (seriesModel, idx) {
185	                if (idx < displaySeriesCnt) {
186	                    let seriesLabel;
187	
188	                    const seriesName = seriesModel.get('name');
189	                    const withName = seriesName ? 'withName' : 'withoutName';
190	                    seriesLabel = seriesCnt > 1
191	                        ? labelModel.get(['series', 'multiple', withName])
192	                        : labelModel.get(['series', 'single', withName]);
193	
194	                    seriesLabel = replace(seriesLabel, {
195	                        seriesId: seriesModel.seriesIndex,
196	                        seriesName: seriesModel.get('name'),
197	                        seriesType: getSeriesTypeName(seriesModel.subType as SeriesTypes)
198	                    });
199	
200	                    const data = seriesModel.getData();
201	                    if (data.count() > maxDataCnt) {
202	                        // Show part of data
203	                        const partialLabel = labelModel.get(['data', 'partialData']);
204	                        seriesLabel += replace(partialLabel, {
205	                            displayCnt: maxDataCnt
206	                        });
207	                    }
208	                    else {
209	                        seriesLabel += labelModel.get(['data', 'allData']);
210	                    }
211	
212	                    const middleSeparator = labelModel.get(['data', 'separator', 'middle']);
213	                    const endSeparator = labelModel.get(['data', 'separator', 'end']);
214	                    const dataLabels = [];
215	                    for (let i = 0; i < data.count(); i++) {
216	                        if (i < maxDataCnt) {
217	                            const name = data.getName(i);
218	                            const value = data.getValues(i);
219	                            const dataLabel = labelModel.get(['data', name ? 'withName' : 'withoutName']);
220	                            dataLabels.push(
221	                                replace(dataLabel, {
222	                                    name: name,
223	                                    value: value.join(middleSeparator)
224	                                })
225	                            );
226	                        }
227	                    }
228	                    seriesLabel += dataLabels.join(middleSeparator) + endSeparator;
229	
230	                    seriesLabels.push(seriesLabel);
231	                }
232	            });
233	
234	            const separatorModel = labelModel.getModel(['series', 'multiple', 'separator']);
235	            const middleSeparator = separatorModel.get('middle');
236	            const endSeparator = separatorModel.get('end');
237	            ariaLabel += seriesLabels.join(middleSeparator) + endSeparator;
238	
239	            dom.setAttribute('aria-label', ariaLabel);
240	        }
241	    }
242	
243	    function replace(str: string, keyValues: object) {
244	        if (!zrUtil.isString(str)) {
245	            return str;
246	        }
247	
248	        let result = str;
249	        zrUtil.each(keyValues, function (value: string, key: string) {
250	            result = result.replace(
251	                new RegExp('\\{\\s*' + key + '\\s*\\}', 'g'),
252	                value
253	            );
254	        });
255	        return result;
256	    }
257	
258	    function getTitle() {
259	        let title = ecModel.get('title') as TitleOption | TitleOption[];
260	        if (title && (title as TitleOption[]).length) {
261	            title = (title as TitleOption[])[0];
262	        }
263	        return title && (title as TitleOption).text;
264	    }
265	
266	    function getSeriesTypeName(type: SeriesTypes) {
267	        const typeNames = ecModel.getLocaleModel().get(['series', 'typeNames']);
268	        return typeNames[type] || typeNames.chart;
269	    }
270	}

    geoId?: string
}

export interface SeriesOnCalendarOptionMixin {
    calendarIndex?: number
    calendarId?: string
}

export interface SeriesLargeOptionMixin {
    large?: boolean
    largeThreshold?: number
}
export interface SeriesStackOptionMixin {
    stack?: string
    stackStrategy?: 'samesign' | 'all' | 'positive' | 'negative';
}

type SamplingFunc = (frame: ArrayLike<number>) => number;

export interface SeriesSamplingOptionMixin {
    sampling?: 'none' | 'average' | 'min' | 'max' | 'minmax' | 'sum' | 'lttb' | SamplingFunc
}

export interface SeriesEncodeOptionMixin {
    datasetIndex?: number;
    datasetId?: string | number;
    seriesLayoutBy?: SeriesLayoutBy;
    sourceHeader?: OptionSourceHeader;
    dimensions?: DimensionDefinitionLoose[];
    encode?: OptionEncode
}

export type SeriesEncodableModel = SeriesModel<SeriesOption & SeriesEncodeOptionMixin>;


// TODO Move to aria component
export interface AriaLabelOption {
    enabled?: boolean;
    description?: string;
    general?: {
        withTitle?: string;
        withoutTitle?: string;
    };
    series?: {
        maxCount?: number;
        single?: {
            prefix?: string;
            withName?: string;
            withoutName?: string;
        };
        multiple?: {
            prefix?: string;
            withName?: string;
            withoutName?: string;
            separator?: {
                middle?: string;
                end?: string;
            }
        }
    };
    data?: {
        maxCount?: number;
        allData?: string;
        partialData?: string;
        withName?: string;
        withoutName?: string;
        separator?: {
            middle?: string;
            end?: string;
        }
    }
}

// Extending is for compating ECharts 4
export interface AriaOption extends AriaLabelOption {
    mainType?: 'aria';

    enabled?: boolean;
    label?: AriaLabelOption;
    decal?: {
        show?: boolean;
        decals?: DecalObject | DecalObject[];
    };
}

export interface AriaOptionMixin {
    aria?: AriaOption
}

