                data: ['a', 'b']
            },
            yAxis: {},
            series: [{
                type: 'bar',
                data: [1, 2]
            }]
        });
        const dom = chart.getDom();
        expect(dom.getAttribute('role')).toEqual('img');
        expect(dom.getAttribute('aria-label')).toContain('This is a chart');
    });

    it('should exclude dimensions by aria.label.data.excludeDimensionId', function () {
