96	function makeCategoryLabels(axis: Axis) {
97	    const labelModel = axis.getLabelModel();
98	    const result = makeCategoryLabelsActually(axis, labelModel);
99	
100	    return (!labelModel.get('show') || axis.scale.isBlank())
101	        ? {labels: [], labelCategoryInterval: result.labelCategoryInterval}
