152	    }
153	    // Always use label interval by default despite label show. Consider this
154	    // scenario, Use multiple grid with the xAxis sync, and only one xAxis shows
155	    // labels. `splitLine` and `axisTick` should be consistent in this case.
156	    else if (optionTickInterval === 'auto') {
157	        const labelsResult = makeCategoryLabelsActually(axis, axis.getLabelModel());
158	        tickCategoryInterval = labelsResult.labelCategoryInterval;
159	        ticks = zrUtil.map(labelsResult.labels, function (labelItem) {
160	            return labelItem.tickValue;
161	        });
162	    }
163	    else {
164	        tickCategoryInterval = optionTickInterval;
165	        ticks = makeLabelsByNumericCategoryInterval(axis, tickCategoryInterval, true);
166	    }
167	
168	    // Cache to avoid calling interval function repeatedly.
169	    return listCacheSet(ticksCache, optionTickInterval as CacheKey, {
170	        ticks: ticks, tickCategoryInterval: tickCategoryInterval
171	    });
172	}
