219	/**
220	 * Calculate interval for category axis ticks and labels.
221	 * To get precise result, at least one of `getRotate` and `isHorizontal`
222	 * should be implemented in axis.
223	 */
224	export function calculateCategoryInterval(axis: Axis) {
225	    const params = fetchAutoCategoryIntervalCalculationParams(axis);
226	    const labelFormatter = makeLabelFormatter(axis);
227	    const rotation = (params.axisRotate - params.labelRotate) / 180 * Math.PI;
228	
229	    const ordinalScale = axis.scale as OrdinalScale;
230	    const ordinalExtent = ordinalScale.getExtent();
231	    // Providing this method is for optimization:
232	    // avoid generating a long array by `getTicks`
233	    // in large category data case.
234	    const tickCount = ordinalScale.count();
235	
236	    if (ordinalExtent[1] - ordinalExtent[0] < 1) {
237	        return 0;
238	    }
239	
240	    let step = 1;
241	    // Simple optimization. Empirical value: tick count should less than 40.
242	    if (tickCount > 40) {
243	        step = Math.max(1, Math.floor(tickCount / 40));
244	    }
245	    let tickValue = ordinalExtent[0];
246	    const unitSpan = axis.dataToCoord(tickValue + 1) - axis.dataToCoord(tickValue);
247	    const unitW = Math.abs(unitSpan * Math.cos(rotation));
248	    const unitH = Math.abs(unitSpan * Math.sin(rotation));
249	
250	    let maxW = 0;
251	    let maxH = 0;
252	
253	    // Caution: Performance sensitive for large category data.
254	    // Consider dataZoom, we should make appropriate step to avoid O(n) loop.
255	    for (; tickValue <= ordinalExtent[1]; tickValue += step) {
256	        let width = 0;
257	        let height = 0;
258	
259	        // Not precise, do not consider align and vertical align
260	        // and each distance from axis line yet.
261	        const rect = textContain.getBoundingRect(
262	            labelFormatter({ value: tickValue }), params.font, 'center', 'top'
263	        );
264	        // Magic number
265	        width = rect.width * 1.3;
266	        height = rect.height * 1.3;
267	
268	        // Min size, void long loop.
269	        maxW = Math.max(maxW, width, 7);
270	        maxH = Math.max(maxH, height, 7);
271	    }
272	
273	    let dw = maxW / unitW;
274	    let dh = maxH / unitH;
275	    // 0/0 is NaN, 1/0 is Infinity.
276	    isNaN(dw) && (dw = Infinity);
277	    isNaN(dh) && (dh = Infinity);
278	    let interval = Math.max(0, Math.floor(Math.min(dw, dh)));
279	
280	    const cache = inner(axis.model);
281	    const axisExtent = axis.getExtent();
282	    const lastAutoInterval = cache.lastAutoInterval;
283	    const lastTickCount = cache.lastTickCount;
284	
285	    // Use cache to keep interval stable while moving zoom window,
286	    // otherwise the calculated interval might jitter when the zoom
287	    // window size is close to the interval-changing size.
288	    // For example, if all of the axis labels are `a, b, c, d, e, f, g`.
289	    // The jitter will cause that sometimes the displayed labels are
290	    // `a, d, g` (interval: 2) sometimes `a, c, e`(interval: 1).
291	    if (lastAutoInterval != null
292	        && lastTickCount != null
293	        && Math.abs(lastAutoInterval - interval) <= 1
294	        && Math.abs(lastTickCount - tickCount) <= 1
295	        // Always choose the bigger one, otherwise the critical
296	        // point is not the same when zooming in or zooming out.
297	        && lastAutoInterval > interval
